interface Printable {
    void print();

    default void printWithBorder() {
        System.out.println("===============");
        print();
        System.out.println("===============");
    }
}

class Document implements Printable {
    @Override
    public void print() {
        System.out.println("Printing document...");
    }
}

public class Main {
    public static void main(String[] args) {
        Printable p = new Document();
        p.printWithBorder();
    }
}
